import re
from datetime import date

_MONTHS = {}
for _idx, _names in enumerate(
    [
        ("jan", "january"),
        ("feb", "february"),
        ("mar", "march"),
        ("apr", "april"),
        ("may",),
        ("jun", "june"),
        ("jul", "july"),
        ("aug", "august"),
        ("sep", "sept", "september"),
        ("oct", "october"),
        ("nov", "november"),
        ("dec", "december"),
    ],
    start=1,
):
    for _name in _names:
        _MONTHS[_name] = _idx

# Leading weekday, e.g. "Tuesday, ", "Tue ", "Thurs. "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues?|wed|thu(?:rs?)?|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)

_MONTH_FIRST = re.compile(
    r"([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})"
)
_DAY_FIRST_NAMED = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+(\d{4})"
)
_YEAR_FIRST_NUMERIC = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_SLASH_NUMERIC = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")


def _make(y: int, m: int, d: int) -> str:
    try:
        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def _month_from_name(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    """Normalize a messy date string to 'YYYY-MM-DD', or return 'INVALID'.

    Numeric dates with a 4-digit year and a shared separator are read as
    day/month/year or month/day/year. If only one reading is a valid date,
    that reading is used. If both are valid, day-first is assumed.
    """
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s).strip()
    t = _WEEKDAY_PREFIX.sub("", t, count=1).strip()
    if not t:
        return "INVALID"

    # Year-first numeric: 2016-02-29, 2016/2/29, 2016.2.29
    m = _YEAR_FIRST_NUMERIC.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact: 20160229
    m = _COMPACT.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric with 4-digit year: 29/02/2000, 02/29/2000, 29-02-2000, 29.02.2000
    m = _SLASH_NUMERIC.fullmatch(t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(3)), int(m.group(4))
        if a > 12 and b <= 12:
            day, month = a, b          # only day-first is possible
        elif b > 12 and a <= 12:
            day, month = b, a          # only month-first is possible
        else:
            day, month = a, b          # ambiguous or invalid: default day-first
        return _make(y, month, day)

    # Month name first: Feb 29, 2016 / February 29th 2016
    m = _MONTH_FIRST.fullmatch(t)
    if m:
        month = _month_from_name(m.group(1))
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(2)))

    # Day first with month name: 29 Feb 2016 / 29th February, 2016
    m = _DAY_FIRST_NAMED.fullmatch(t)
    if m:
        month = _month_from_name(m.group(2))
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(1)))

    return "INVALID"

import re
from datetime import date

_MONTHS = {}
for _i, _name in enumerate(
    ["january", "february", "march", "april", "may", "june",
     "july", "august", "september", "october", "november", "december"], 1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "Thu "
_WEEKDAY_PREFIX = re.compile(
    r"(?i)^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+"
)


def _make(y: int, m: int, d: int) -> str:
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return "INVALID"


def _month_from_name(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    t = s.strip()
    if not t:
        return "INVALID"

    # Drop an optional leading weekday name.
    t = _WEEKDAY_PREFIX.sub("", t, count=1).strip()
    if not t:
        return "INVALID"

    # Year-first numeric with a consistent separator: YYYY-M-D, YYYY/M/D, YYYY.M.D
    m = re.fullmatch(r"([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})", t, re.ASCII)
    if m:
        return _make(int(m[1]), int(m[3]), int(m[4]))

    # Compact: YYYYMMDD
    m = re.fullmatch(r"([0-9]{4})([0-9]{2})([0-9]{2})", t, re.ASCII)
    if m:
        return _make(int(m[1]), int(m[2]), int(m[3]))

    # Numeric D?-M?-YYYY with separators - / . ; day-first convention.
    m = re.fullmatch(r"([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})", t, re.ASCII)
    if m:
        d, mo, y = int(m[1]), int(m[3]), int(m[4])
        return _make(y, mo, d)

    # "Month D, YYYY" or "Mon D YYYY"
    m = re.fullmatch(
        r"([A-Za-z]{3,9})\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})",
        t, re.ASCII)
    if m:
        mon = _month_from_name(m[1])
        if mon:
            return _make(int(m[3]), mon, int(m[2]))
        return "INVALID"

    # "D Month YYYY" or "D Mon YYYY"
    m = re.fullmatch(
        r"([0-9]{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+([0-9]{4})",
        t, re.ASCII)
    if m:
        mon = _month_from_name(m[2])
        if mon:
            return _make(int(m[3]), mon, int(m[1]))
        return "INVALID"

    return "INVALID"

import re
import datetime

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ORD = r"(?:st|nd|rd|th)?"
_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)"
    r"(?:day|nesday|sday|rsday|urday)?\.?,?\s+",
    re.IGNORECASE,
)

# YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
_YMD_SEP = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
# YYYYMMDD
_YMD_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
# DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY (day-first convention)
_DMY_SEP = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")
# 31 December 1999, 31st Dec. 1999, 31-Dec-1999
_DAY_MON_YEAR = re.compile(
    r"(\d{1,2})" + _ORD + r"[ \-]+([A-Za-z]+)\.?,?[ \-]+(\d{4})",
    re.IGNORECASE,
)
# December 31, 1999 / Dec 31st 1999 / Dec-31-1999
_MON_DAY_YEAR = re.compile(
    r"([A-Za-z]+)\.?[ \-]+(\d{1,2})" + _ORD + r",?[ \-]+(\d{4})",
    re.IGNORECASE,
)


def _make(year: str, month: int, day: str) -> str:
    try:
        return datetime.date(int(year), int(month), int(day)).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    s = " ".join(s.split())
    if not s:
        return "INVALID"

    s = _WEEKDAY_PREFIX.sub("", s, count=1).strip()
    if not s:
        return "INVALID"

    m = _YMD_SEP.fullmatch(s)
    if m:
        y, _, mo, d = m.groups()
        return _make(y, int(mo), d)

    m = _YMD_COMPACT.fullmatch(s)
    if m:
        y, mo, d = m.groups()
        return _make(y, int(mo), d)

    m = _DMY_SEP.fullmatch(s)
    if m:
        d, _, mo, y = m.groups()
        return _make(y, int(mo), d)

    m = _DAY_MON_YEAR.fullmatch(s)
    if m:
        d, name, y = m.groups()
        month = _month_number(name)
        if month is None:
            return "INVALID"
        return _make(y, month, d)

    m = _MON_DAY_YEAR.fullmatch(s)
    if m:
        name, d, y = m.groups()
        month = _month_number(name)
        if month is None:
            return "INVALID"
        return _make(y, month, d)

    return "INVALID"
